<?php
require __DIR__.'/includes/bootstrap.php';$user=require_login('buyer');$q=$pdo->prepare("SELECT o.*,p.name product_name,u.full_name farmer_name,u.phone farmer_phone FROM orders o JOIN products p ON p.id=o.product_id JOIN users u ON u.id=o.farmer_id WHERE o.buyer_id=? ORDER BY o.created_at DESC");$q->execute([$user['id']]);$orders=$q->fetchAll();$pageTitle='My orders';require __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow" style="color:var(--green)">Buyer workspace</span><h1 style="font-size:clamp(2rem,4vw,3.4rem)">My orders</h1><p>Track requests and contact farmers to confirm the details.</p></section><div class="section" style="padding-top:0"><section class="panel"><?php if($orders): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Requested</th><th>Product</th><th>Farmer</th><th>Quantity</th><th>Est. total</th><th>Payment / fulfillment</th><th>Status</th><th>Contact</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= e(date('M j, Y',strtotime($o['created_at']))) ?></td><td><?= e($o['product_name']) ?></td><td><?= e($o['farmer_name']) ?></td><td><?= e(rtrim(rtrim((string)$o['quantity'],'0'),'.')) ?></td><td><?= money($o['total']) ?></td><td><?= e(str_replace('_',' ',$o['payment_method'])) ?><br><?= e($o['fulfillment']) ?></td><td><span class="status status-<?= e($o['status']) ?>"><?= e(str_replace('_',' ',$o['status'])) ?></span></td><td><?= e($o['farmer_phone']) ?><?php if($o['status']==='new'): ?><form method="post" action="/cancel-order.php" style="margin-top:7px" data-confirm="Cancel this order request?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><button class="button button-small button-quiet">Cancel request</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><h3>No orders yet</h3><p>When you find a harvest you like, send a request to start coordinating.</p><a class="button" href="/market.php">Browse the market</a></div><?php endif; ?></section></div>
<?php require __DIR__.'/includes/footer.php'; ?>
